package com.example.bookmyticket.controller; import com.example.bookmyticket.dto.*; import com.example.bookmyticket.service.BookingService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api") public class BookingController {private final BookingService service;public BookingController(BookingService s){service=s;} @GetMapping("/shows/{id}/seats") public List<SeatDto> seats(@PathVariable Long id){return service.getSeats(id);} @PostMapping("/bookings") public BookingDto book(@Valid @RequestBody BookingRequest r){return service.create(r);} @GetMapping("/bookings") public List<BookingDto> history(@RequestParam String email){return service.history(email);}}
